@@ -0,0 +1,54 @@
+package server
+
+import (
+	"bytes"
+	"encoding/json"
+	"net/http"
+	"net/http/httptest"
+	"testing"
+)
+
+func TestRateLimitLogin(t *testing.T) {
+	app := New(Config{DataDir: t.TempDir()})
+	defer app.Close()
+
+	signupReq := map[string]string{
+		"email":    "test@example.com",
+		"password": "password123456",
+	}
+	body, _ := json.Marshal(signupReq)
+	req := httptest.NewRequest("POST", "/api/signup", bytes.NewReader(body))
+	req.Header.Set("Content-Type", "application/json")
+	w := httptest.NewRecorder()
+	app.ServeHTTP(w, req)
+	if w.Code != http.StatusCreated {
+		t.Fatalf("signup failed: %d", w.Code)
+	}
+
+	loginReq := map[string]string{
+		"email":    "test@example.com",
+		"password": "password123456",
+	}
+
+	for i := 0; i < 10; i++ {
+		body, _ = json.Marshal(loginReq)
+		req = httptest.NewRequest("POST", "/api/login", bytes.NewReader(body))
+		req.Header.Set("Content-Type", "application/json")
+		req.RemoteAddr = "192.168.1.1:12345"
+		w = httptest.NewRecorder()
+		app.ServeHTTP(w, req)
+		if w.Code != http.StatusOK {
+			t.Fatalf("login %d failed: %d", i+1, w.Code)
+		}
+	}
+
+	body, _ = json.Marshal(loginReq)
+	req = httptest.NewRequest("POST", "/api/login", bytes.NewReader(body))
+	req.Header.Set("Content-Type", "application/json")
+	req.RemoteAddr = "192.168.1.1:12345"
+	w = httptest.NewRecorder()
+	app.ServeHTTP(w, req)
+	if w.Code != http.StatusTooManyRequests {
+		t.Errorf("expected 429 on 11th login, got %d", w.Code)
+	}
+}
